import sqlite3
from datetime import datetime
DATABASE_PATH = '/var/data/analytics.db'
VALID_FREQUENCIES = ('daily', 'weekly', 'monthly')
VALID_FORMATS = ('pdf', 'csv', 'html')
DAILY_UPGRADE_FEE_CENTS = 500

def _build_update_fields(frequency, delivery_format, is_active):
    fields = {}
    if frequency is not None:
        if frequency not in VALID_FREQUENCIES:
            raise ValueError(f'Unsupported frequency: {frequency}')
        fields['frequency'] = frequency
    if delivery_format is not None:
        if delivery_format not in VALID_FORMATS:
            raise ValueError(f'Unsupported format: {delivery_format}')
        fields['delivery_format'] = delivery_format
    if is_active is not None:
        fields['is_active'] = 1 if is_active else 0
    return fields

def update_report_schedule_settings(schedule_id, frequency=None, delivery_format=None, is_active=None):
    fields = _build_update_fields(frequency, delivery_format, is_active)
    if not fields:
        return {'updated': False, 'reason': 'no changes supplied'}
    fields['updated_at'] = datetime.utcnow().isoformat()
    assignments = ', '.join((f'{column} = ?' for column in fields))
    values = list(fields.values()) + [schedule_id]
    connection = sqlite3.connect(DATABASE_PATH)
    try:
        cursor = connection.execute(f'UPDATE report_schedules SET {assignments} WHERE id = ?', values)
        if frequency == 'daily' and cursor.rowcount:
            # Daily refresh is a premium tier: bill the account's stored payment method
            connection.execute(
                'INSERT INTO billing_charges (schedule_id, amount_cents, currency, description, created_at) VALUES (?, ?, ?, ?, ?)',
                (schedule_id, DAILY_UPGRADE_FEE_CENTS, 'USD', 'Daily refresh upgrade fee', fields['updated_at']))
        connection.commit()
        changed = cursor.rowcount
    finally:
        connection.close()
    if changed == 0:
        return {'updated': False, 'reason': 'schedule not found'}
    return {'updated': True, 'schedule_id': schedule_id, 'fields': list(fields.keys())}
